import {createAPI, escapeHTML as esc, sourceURL, eligibility, filterOpportunities} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let token='', mode='login', opps=[], favs=[], applications=[], collection='favorites', toastTimer, epoch=0;
let loaded={opps:false,favs:false,apps:false,me:false};
const loading='<div class="empty loading" role="status"><span class="loadingMark" aria-hidden="true">✦</span><p>Preparando tu espacio…</p></div>';
const unavailable=()=>empty('No hemos podido cargar esta sección.','Pulsa Reintentar arriba para recuperar los datos.');
try { token=localStorage.getItem('pplus_token') || ''; } catch {}
const api=createAPI(()=>token);
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('on');toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),5000);}
function storeToken(value){token=value;try{value?localStorage.setItem('pplus_token',value):localStorage.removeItem('pplus_token');}catch{toast('El navegador no permite recordar la sesión.');}}
function authUI(ok){$('#auth').classList.toggle('hidden',ok);$('#product').classList.toggle('hidden',!ok);$('#logout').classList.toggle('hidden',!ok);document.title=ok?'Tu espacio · Proyecta-T':'Entrar · Proyecta-T';}
function logout(){epoch++;api.cancel();storeToken('');opps=[];favs=[];applications=[];loaded={opps:false,favs:false,apps:false,me:false};$('#profileGuide').classList.add('hidden');$('#profileStatus').textContent='';$('#dossierStatus').textContent='';$('#profileForm').reset();$('#dossierForm').reset();$('#draft').value='';$('#dossierOut').classList.add('hidden');$('#password').value='';$('#hello').textContent='';['#best','#opps','#favoritesList','#appsList'].forEach(s=>$(s).replaceChildren());$('#loadError').classList.add('hidden');authUI(false);}
function fail(error){if(error.name==='AbortError')return;if(error.status===401&&token){logout();$('#msg').textContent='Tu sesión ha caducado. Vuelve a entrar.';}else toast(error.message);}
async function busy(button,action){if(button.disabled)return;const label=button.textContent;button.disabled=true;button.textContent='Un momento…';try{await action();}catch(error){fail(error);}finally{button.disabled=false;button.textContent=label;}}
function setMode(next){mode=next;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('#nameField').classList.toggle('hidden',mode!=='signup');$('#name').required=false;$('#passwordHint').classList.toggle('hidden',mode!=='signup');$('#password').minLength=mode==='signup'?8:1;$('#password').autocomplete=mode==='signup'?'new-password':'current-password';$('#authTitle').textContent=mode==='signup'?'Haz sitio a lo que viene.':'Qué bien verte.';$('#authBtn').textContent=mode==='signup'?'Crear cuenta →':'Entrar →';$('#msg').textContent='';}
$$('[data-mode]').forEach(b=>b.onclick=()=>{if(!$('#authBtn').disabled)setMode(b.dataset.mode);});
$('#showPassword').onclick=()=>{const show=$('#password').type==='password';$('#password').type=show?'text':'password';$('#showPassword').textContent=show?'Ocultar':'Mostrar';$('#showPassword').setAttribute('aria-pressed',String(show));};
$('#authForm').onsubmit=e=>{e.preventDefault();busy($('#authBtn'),async()=>{const data={email:$('#email').value.trim(),password:$('#password').value};if(mode==='signup')data.name=$('#name').value.trim();$('#msg').textContent='';try{const result=await api('/api/'+mode,{method:'POST',body:JSON.stringify(data)});if(typeof result.token!=='string'||!result.token)throw Error('No se recibió una sesión válida.');storeToken(result.token);$('#password').value='';await boot();}catch(error){$('#msg').textContent=error.message;}});};
$('#logout').onclick=logout;
function empty(title,detail){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;}
function card(o){const state=eligibility(o),e=o.eligibility||{},favorite=favs.includes(o.id),source=sourceURL(o.source),id=Number(o.id);if(!Number.isSafeInteger(id))return '';
return `<article class="card"><div class="row"><span class="chip">${esc(o.type||'Oportunidad')}</span><button class="favorite secondary" data-fav="${id}" ${loaded.favs?'':'disabled'} aria-pressed="${favorite}" aria-label="${favorite?'Quitar de':'Añadir a'} favoritos: ${esc(o.title)}">${favorite?'♥':'♡'}</button></div><h3 class="cardTitle">${esc(o.title)}</h3><p class="meta">${esc(o.org)} · ${esc(o.location||'Ubicación por consultar')}</p><p class="cardSummary">${esc(o.summary)}</p><div class="chips"><span class="chip ${state==='ready'?'ok':state==='excluded'?'bad':'warn'}">${state==='ready'?'Encaje inicial':state==='excluded'?'Con exclusiones':'Por completar'}</span>${Number.isFinite(o.match)?`<span class="chip">${esc(o.match)}% de afinidad orientativa</span>`:''}</div><p class="meta">${esc(o.deadline||'Consulta el plazo en las bases')} · ${esc(o.amount||'Dotación por consultar')}</p>${e.reasons?.length?`<p class="error">${esc(e.reasons.join(' · '))}</p>`:''}${e.unknown?.length?`<p class="hint">Falta comprobar: ${esc(e.unknown.join(', '))}</p>`:''}<p class="hint">${esc(({verified:'Verificada',unverified:'No verificada',stale:'No verificada · sin actividad reciente',closed:'Cerrada'})[o.status]||'No verificada')} · ${esc(o.last_checked_at?.slice(0,10)||'Sin fecha de comprobación')}. ${esc(o.evidence||'')} Revisa el resto de requisitos y el plazo en las bases.</p>${state==='ready'?`<button class="primary" data-start="${id}">Preparar candidatura →</button>`:state==='pending'?'<button class="secondary" data-go="perfil">Completar perfil →</button>':'<p class="hint">Esta oportunidad no permite iniciar una candidatura desde tu perfil actual.</p>'}${source?`<a class="sourceLink" href="${esc(source)}" target="_blank" rel="noopener noreferrer">${esc(o.source_name||'Ver bases oficiales')} ↗</a>`:''}</article>`;}
function render(){if(!loaded.opps)return;$('#clearFilters').classList.toggle('hidden',!($('#search').value||$('#typeFilter').value||$('#eligibilityFilter').value||$('#areaFilter').value||$('#verificationFilter').value));const rows=filterOpportunities(opps,$('#search').value,$('#typeFilter').value,$('#eligibilityFilter').value,$('#areaFilter').value,$('#verificationFilter').value).filter(o=>$('#verificationFilter').value || !['closed','stale'].includes(o.status));$('#opps').innerHTML=rows.map(card).join('')||empty('Nada por aquí, todavía.','Prueba otra búsqueda o cambia los filtros.');$('#resultCount').textContent=`${rows.length} oportunidades`;$('#best').innerHTML=opps.filter(o=>o.verified && eligibility(o)!=='excluded').slice(0,3).map(card).join('')||empty('Tu siguiente oportunidad está por llegar.','Explora el catálogo público o completa tu perfil.');$('#eligibleCount').textContent=opps.filter(o=>eligibility(o)==='ready').length;$('#favoriteCount').textContent=loaded.favs?favs.length:'—';$('#summary').textContent=`${opps.length} oportunidades para explorar. Tu próximo paso lo eliges tú.`;if(loaded.favs)$('#favoritesList').innerHTML=opps.filter(o=>favs.includes(o.id)).map(card).join('')||empty('Guarda lo que te mueve.','Pulsa el corazón de una oportunidad para encontrarla aquí.');const selected=$('#dossierOpp').value;$('#dossierOpp').innerHTML='<option value="">Selecciona una oportunidad</option>'+opps.filter(o=>eligibility(o)==='ready').map(o=>`<option value="${Number(o.id)}">${esc(o.title)}</option>`).join('');$('#dossierOpp').value=selected;const ready=opps.some(o=>eligibility(o)==='ready');$('#generate').disabled=!ready;$('#dossierHelp').textContent=ready?'Obtendrás un borrador editable. Revísalo y adáptalo a las bases antes de enviarlo.':'Todavía no hay oportunidades con encaje inicial confirmado. Revisa tu perfil y vuelve al radar.';}
function renderApps(){$('#appsList').innerHTML=applications.map(a=>`<article class="card"><span class="chip">${esc(a.status)}</span><h3 class="cardTitle">${esc(a.title)}</h3><p class="meta">${esc(a.deadline||'Consulta el plazo en las bases')}</p>${a.status!=='Enviada'?`<button class="secondary" data-sent="${Number(a.opportunity_id)}">Ya la he enviado</button>`:'<p class="hint">Envío anotado en tu seguimiento.</p>'}</article>`).join('')||empty('Aquí empieza el camino.','Prepara una candidatura desde el radar y sigue sus avances.');}
async function loadOpps(){const data=await api('/api/opportunities?include_inactive=true');if(!Array.isArray(data))throw Error('No se pudo leer el radar.');opps=data;loaded.opps=true;const type=$('#typeFilter').value;$('#typeFilter').innerHTML='<option value="">Todos los tipos</option>'+[...new Set(opps.map(o=>o.type).filter(Boolean))].sort().map(t=>`<option>${esc(t)}</option>`).join('');$('#typeFilter').value=type;render();}
async function loadFavs(){const data=await api('/api/favorites');if(!Array.isArray(data))throw Error('No se pudieron leer los favoritos.');favs=data;loaded.favs=true;render();}
async function loadApps(){const data=await api('/api/applications');if(!Array.isArray(data))throw Error('No se pudieron leer las candidaturas.');applications=data;loaded.apps=true;renderApps();}
async function loadMe(){const m=await api('/api/me');loaded.me=true;const missing=[!m.discipline&&'tu disciplina',!m.location&&'tu ubicación',!m.interests&&'tus intereses'].filter(Boolean);$('#profileGuide').classList.toggle('hidden',!missing.length);$('#profileGuideText').textContent='Añade '+missing.join(', ')+' para orientar mejor tu radar.';$('#hello').textContent=m.name||m.email||'';for(const [id,key] of Object.entries({pName:'name',pDisc:'discipline',pLoc:'location',pInt:'interests',pBirth:'birth_year'}))$('#'+id).value=m[key]??'';}
function go(id,history=true){if(!['inicio','radar','apps','dossier','perfil'].includes(id))id='inicio';$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottomNav button').forEach(b=>{b.classList.toggle('active',b.dataset.go===id);b.dataset.go===id?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});document.title=({inicio:'Tu espacio',radar:'Radar',apps:'Mi selección',dossier:'Dossier',perfil:'Perfil'}[id])+' · Proyecta-T';if(history&&location.hash!=='#'+id)location.hash=id;$('#'+id).focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
addEventListener('hashchange',()=>go(location.hash.slice(1),false));
function setCollection(value){collection=value;$$('[data-collection]').forEach(b=>{b.classList.toggle('active',b.dataset.collection===collection);b.setAttribute('aria-pressed',String(b.dataset.collection===collection));});$('#favoritesList').classList.toggle('hidden',collection!=='favorites');$('#appsList').classList.toggle('hidden',collection!=='applications');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.go)go(b.dataset.go);if(b.dataset.collection)setCollection(b.dataset.collection);if(b.dataset.fav)busy(b,async()=>{const id=Number(b.dataset.fav),exists=favs.includes(id);await api('/api/favorites/'+id,{method:exists?'DELETE':'POST'});favs=exists?favs.filter(x=>x!==id):[...favs,id];render();toast(exists?'Eliminada de favoritos':'Guardada en tu selección');});if(b.dataset.start)busy(b,async()=>{await api('/api/applications/'+Number(b.dataset.start),{method:'POST'});await loadApps();setCollection('applications');go('apps');toast('Candidatura preparada. El envío se hace en la web oficial.');});if(b.dataset.sent)busy(b,async()=>{await api('/api/applications/'+Number(b.dataset.sent)+'/sent',{method:'PUT'});await loadApps();toast('Envío anotado');});});
$('#clearFilters').onclick=()=>{$('#search').value='';$('#typeFilter').value='';$('#eligibilityFilter').value='';$('#areaFilter').value='';$('#verificationFilter').value='';render();$('#search').focus();};
$('#areaFilter').onchange=render;$('#verificationFilter').onchange=render;
$('#search').oninput=render;$('#typeFilter').onchange=render;$('#eligibilityFilter').onchange=render;
$('#profileForm').onsubmit=e=>{e.preventDefault();busy($('#saveProfile'),async()=>{await api('/api/me',{method:'PUT',body:JSON.stringify({name:$('#pName').value.trim(),discipline:$('#pDisc').value.trim(),location:$('#pLoc').value.trim(),interests:$('#pInt').value.trim(),birth_year:$('#pBirth').value?Number($('#pBirth').value):null})});$('#profileStatus').textContent='Perfil guardado. Tu radar se ha actualizado con estos datos.';toast('Perfil guardado');await Promise.all([loadMe(),loadOpps()]);});};
$('#pBirth').max=new Date().getFullYear();
$('#dossierForm').onsubmit=e=>{e.preventDefault();busy($('#generate'),async()=>{const r=await api('/api/dossier',{method:'POST',body:JSON.stringify({opportunity_id:Number($('#dossierOpp').value),project_focus:$('#focus').value.trim()})});$('#draft').value=`BIO\n${r.bio||''}\n\nMOTIVACIÓN\n${r.motivation||''}\n\nANTES DE ENVIAR\n${(r.checklist||[]).map(x=>'☐ '+x).join('\n')}`;$('#dossierStatus').textContent='Tu borrador está listo. Puedes editarlo debajo.';$('#dossierOut').classList.remove('hidden');$('#draft').focus();toast('Borrador creado. Puedes editarlo antes de descargar.');});};
$('#preview-draft').onclick=()=>window.ProyectaPreview('Mi dossier',[{style:'body',text:$('#draft').value}]);
$('#download').onclick=()=>busy($('#download'),()=>window.ProyectaDownload(new Blob([$('#draft').value],{type:'text/plain;charset=utf-8'}),'Proyecta-T-dossier.txt'));
function connection(){const offline=!navigator.onLine;$('#connection').classList.toggle('hidden',!offline);$('#connection').textContent='Sin conexión. Tu sesión se conserva; recupera internet para guardar cambios o actualizar datos.';}
addEventListener('online',connection);addEventListener('offline',connection);connection();
async function boot(){if(!token){authUI(false);return;}const current=++epoch;authUI(true);go(location.hash.slice(1)||'inicio',false);$('#loadError').classList.add('hidden');$('#product').setAttribute('aria-busy','true');if(!loaded.opps){$('#best').innerHTML=loading;$('#opps').innerHTML=loading;$('#eligibleCount').textContent='—';$('#summary').textContent='Buscando oportunidades para tu siguiente paso…';}if(!loaded.favs)$('#favoritesList').innerHTML=loading;if(!loaded.apps)$('#appsList').innerHTML=loading;$$('#profileForm input,#profileForm textarea,#saveProfile').forEach(e=>e.disabled=!loaded.me);$('#generate').disabled=!loaded.opps;const results=await Promise.allSettled([loadMe(),loadOpps(),loadFavs(),loadApps()]);if(current!==epoch)return;$('#product').removeAttribute('aria-busy');$$('#profileForm input,#profileForm textarea,#saveProfile').forEach(e=>e.disabled=!loaded.me);if(!loaded.opps){$('#best').innerHTML=unavailable();$('#opps').innerHTML=unavailable();$('#summary').textContent='Tu sesión está abierta. Reintenta la carga para ver las oportunidades.';}if(!loaded.favs)$('#favoritesList').innerHTML=unavailable();if(!loaded.apps)$('#appsList').innerHTML=unavailable();const errors=results.filter(r=>r.status==='rejected').map(r=>r.reason);if(errors.some(e=>e.status===401)){fail(errors.find(e=>e.status===401));return;}if(errors.length){$('#loadError span').textContent='No se han podido actualizar todos los datos. '+errors[0].message;$('#loadError').classList.remove('hidden');}}
$('#retry').onclick=()=>busy($('#retry'),boot);
boot();

if(window.Capacitor?.isNativePlatform?.())$('#download').textContent='Compartir o guardar texto';

setInterval(()=>{if(token && document.visibilityState==='visible')loadOpps().catch(fail);},60000);
